def stories_and_permission(p):
 seed(p);go(p,18);p.get_by_role('button',name='写一页成长故事',exact=True).click();p.get_by_label('成长故事内容',exact=True).fill('今天带团团去看了花');p.get_by_role('button',name='保存成长故事',exact=True).click();expect(p.locator('dialog[open]')).to_have_count(0);p.get_by_role('button',name='今天带团团去看了花',exact=False).click();p.wait_for_url('**/m07-p19.html*');expect(p.locator('.note')).to_have_text('今天带团团去看了花');p.get_by_role('button',name='回应这一页',exact=True).click();p.get_by_label('回应内容',exact=True).fill('下次也一起去');p.get_by_role('button',name='保存回应',exact=True).click();expect(p.locator('dialog[open]')).to_have_count(0);expect(p.locator('.reply')).to_contain_text('下次也一起去');go(p,18);p.evaluate('localStorage.setItem("dujia-prototype-records",JSON.stringify([{id:"source-one",type:"diary",title:"一起散步",body:"只向共同空间展示",visibility:"shared",status:"published",author:"阿舟"}]))');p.get_by_role('button',name='关联共同记录',exact=True).click();p.get_by_role('button',name='一起散步',exact=True).click();expect(p.locator('dialog[open]')).to_have_count(0);p.get_by_role('button',name='一起散步',exact=False).click();p.wait_for_url('**/m07-p19.html*');p.evaluate('(()=>{let rows=JSON.parse(localStorage.getItem("dujia-prototype-records"));rows[0].visibility="private";localStorage.setItem("dujia-prototype-records",JSON.stringify(rows));})()');p.reload();p.wait_for_url('**/m07-p17.html*');expect(p.locator('.reason')).to_contain_text('不可见');assert '只向共同空间展示' not in p.locator('body').inner_text()
def achievement_rewards(p):
 seed(p);go(p,21);p.get_by_role('button',name='陪伴30天',exact=False).click();p.wait_for_url('**/m07-p20.html*');p.locator('.claim').click();expect(p.locator('.claim')).to_have_text('奖励已领取');assert value(p)['stars']==60;p.reload();expect(p.locator('.claim')).to_be_disabled();go(p,22);p.locator('[data-tab=纪念物]').click();p.get_by_role('button',name='陪伴30天 已拥有',exact=True).click();p.wait_for_url('**/m07-p23.html*');expect(p.locator('#wearState')).to_contain_text('已领取')
def pause_export_resume(p):
 seed(p);go(p,25);p.locator('.r6').click();p.wait_for_url('**/m07-p24.html');
 with p.expect_download() as dl:p.locator('#export').click()
 data=json.loads(Path(dl.value.path()).read_text(encoding='utf-8'));assert data['name']=='团团' and data['logs'][0]['id']=='first' and data['days']==35;p.locator('#unlink').click();p.get_by_role('button',name='确认暂停',exact=True).click();p.wait_for_url('**/m07-p25.html');assert value(p)['care'] is False;assert value(p)['owned']==['小花围巾'];p.locator('.r6').click();p.get_by_role('button',name='重新开始照顾',exact=True).click();expect(p.locator('.day')).to_contain_text('共同照顾中');assert value(p)['care'] is True
rows=[]
with sync_playwright() as pw:
 b=pw.chromium.launch(headless=True,executable_path=r'C:\Program Files\Google\Chrome\Application\chrome.exe')
 for name,run in {'outfit-collection-room-save':wardrobe_room,'story-reply-source-privacy':stories_and_permission,'achievement-idempotent-collection':achievement_rewards,'pause-real-export-resume':pause_export_resume}.items():
  c=b.new_context(viewport={'width':390,'height':844},accept_downloads=True);p=c.new_page();p.set_default_timeout(4500);errors=[];p.on('pageerror',lambda e:errors.append(str(e)))
  try:run(p);assert not errors,errors;row={'case':name,'passed':True}
  except Exception as e:row={'case':name,'passed':False,'failure':repr(e)[:1700]}
  row.update(errors=errors,final_url=p.url);rows.append(row);(OUT/'pet-life-flow-results.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2),encoding='utf-8');print(('PASS ' if row['passed'] else 'FAIL ')+name,flush=True);c.close()
 b.close()
raise SystemExit(0 if all(r['passed'] for r in rows) else 1)
